#define main preserved_native_main
#include "../radixsort2-cuda/main.cu"
#undef main
#include <vector>
#include <cstdint>
#include <cstring>
#include <thrust/version.h>
template<class T>std::vector<T>read(const char*n){FILE*f=fopen(n,"rb");if(!f)exit(3);fseek(f,0,SEEK_END);long bytes=ftell(f);rewind(f);std::vector<T>a(bytes/sizeof(T));fread(a.data(),sizeof(T),a.size(),f);fclose(f);return a;}
template<class T>int study(bool fp,bool only){constexpr size_t N=1048576;constexpr int REPS=100;auto input=read<T>(fp?"study_input_f32.bin":"study_input_u32.bin"),expected=read<T>(fp?"study_expected_keys_f32.bin":"study_expected_keys_u32.bin");auto values=read<unsigned>("study_input_values_u32.bin");thrust::device_vector<T>keys(N);thrust::device_vector<unsigned>vals(only?0:N);auto reset=[&](){cudaMemcpy(thrust::raw_pointer_cast(keys.data()),input.data(),N*sizeof(T),cudaMemcpyHostToDevice);if(!only)cudaMemcpy(thrust::raw_pointer_cast(vals.data()),values.data(),N*4,cudaMemcpyHostToDevice);};auto execute=[&](){if(only)thrust::sort(keys.begin(),keys.end());else thrust::sort_by_key(keys.begin(),keys.end(),vals.begin());};reset();execute();if(cudaDeviceSynchronize()!=cudaSuccess)return 4;printf("THRUST_COMPILED_VERSION %d\n",THRUST_VERSION);bool all=true;for(int trial=1;trial<=5;trial++){double seconds=0;for(int rep=0;rep<REPS;rep++){reset();cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();execute();if(cudaDeviceSynchronize()!=cudaSuccess)return 4;seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/REPS;}thrust::host_vector<T>host=keys;thrust::host_vector<unsigned>hv=vals;bool ok=true;double ma=0;std::vector<bool>seen(N,false);for(size_t i=0;i<N;i++){ok&=host[i]==expected[i];ma=std::max(ma,fabs(double(host[i])-double(expected[i])));if(!only){unsigned id=hv[i];if(id>=N||seen[id])ok=false;else{seen[id]=true;ok&=host[i]==input[id];}}}all&=ok;std::vector<double>out;out.reserve((only?2:4)*N+5);for(auto a:input)out.push_back(double(a));if(!only)for(auto a:values)out.push_back(a);out.insert(out.end(),{double(N),double(only),double(fp),double(REPS),32.});for(auto a:host)out.push_back(double(a));if(!only)for(auto a:hv)out.push_back(a);char name[100];snprintf(name,100,"output_trial%d.bin",trial);FILE*f=fopen(name,"wb");fwrite(out.data(),8,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"error_metric_domain\":\"sorted_keys_exact_plus_pair_permutation_association_properties\",\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",out.size(),ma,ma,REPS,name,out.size());}return all?0:1;}
int main(int argc,char**argv){bool fp=atoi(argv[1]),only=atoi(argv[2]);return fp?study<float>(fp,only):study<unsigned>(fp,only);}
